window.SIMX = [{"id":"s1","src":"ETC","pav":"Šlaunies amputacija","tema":"Kraujavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":28,"temp":36.6},"p":"Iš pozicijų atvežamas karys po minos sprogimo: kairės šlaunies amputacija, iš kelmo pulsuojamai bėga kraujas. Pakeliui uždėtas turniketas atsilaisvino ir nusmuko. A atlieka 5 s apžiūrą. (AVPU V)","k":"Ką pirmiausia daro komandos vadas A?"},{"n":"2 klausimas","v":{"hr":124,"sys":92,"dia":60,"spo2":97,"rr":28,"temp":36.6},"p":"Turniketas uždėtas ant odos 5–8 cm virš kelmo krašto, strypas pasuktas. Kraujavimas iš kelmo sumažėjo, bet tebesisunkia.","k":"Ką daryti toliau?"},{"n":"3 klausimas","v":{"hr":132,"sys":84,"dia":50,"spo2":97,"rr":28,"temp":36.6},"p":"Kraujavimas sustojo, laikas užrašytas ant turniketo. C praneša: hemoraginis šokas – taip. Trauma įvyko prieš 50 min. (AVPU V)","k":"Kuris tolesnis žingsnis teisingas?"}]},{"id":"s2","src":"ETC","pav":"Kraujas burnoje","tema":"Kvėpavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":88,"rr":8,"temp":36.6},"p":"Šarvuočio vairuotojas po apvirtimo, veido trauma. Reaguoja tik į skausmą, girdimas burbuliavimas, burnoje kraujas. Kaklo trauma neatmesta. (AVPU P)","k":"Kaip A atveria kvėpavimo takus?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":91,"rr":8,"temp":36.6},"p":"Po atsiurbimo takai laisvesni, bet atleidus žandikaulį liežuvis vėl užkrenta. Matomos „akinių“ kraujosruvos ir skystis iš nosies. Vėmimo reflekso nėra. (AVPU P)","k":"Kuri pagalbinė priemonė tinkama?"},{"n":"3 klausimas","v":{"hr":48,"sys":120,"dia":78,"spo2":74,"rr":8,"temp":36.6},"p":"Ventiliacija kauke, laringine kauke ir intubacija nepavyksta – po 3 bandymų kiekvienu būdu. Krūtinė nekyla, SpO₂ krenta. Ekspertinė pagalba pakviesta.","k":"Ką skelbia A?"}]},{"id":"s3","src":"ETC","pav":"Siurbianti krūtinės žaizda","tema":"Krūtinė","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":118,"dia":76,"spo2":90,"rr":30,"temp":36.6},"p":"Karys sužeistas peiliu artimoje kovoje – dūris į dešinę krūtinės pusę. B mato žaizdą, kuri įkvepiant burbuliuoja ir švilpia.","k":"Ką daro B?"},{"n":"2 klausimas","v":{"hr":136,"sys":82,"dia":50,"spo2":83,"rr":38,"temp":36.6},"p":"Po 5 min pacientas blogėja: dešinėje negirdėti kvėpavimo garsų, perkutuojant dėžinis garsas, išsiplėtusios kaklo venos.","k":"Kas teisinga?"},{"n":"3 klausimas","v":{"hr":136,"sys":80,"dia":48,"spo2":82,"rr":38,"temp":36.6},"p":"Gydytojas dar neatvyko. B atliko adatinę dekompresiją 14 G kanule 4–5 tarpšonkaulyje tarp priekinės ir vidurinės pažasties linijų. Oro išėjimo negirdėti, būklė negerėja.","k":"Kaip vertinti šią situaciją?"}]},{"id":"s4","src":"ETC","pav":"Šokas be hipotenzijos","tema":"Šokas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":122,"sys":104,"dia":72,"spo2":97,"rr":16,"temp":36.6},"p":"Karį prieš 40 min poligone partrenkė karinis visureigis. Galvos traumos požymių nėra, bet sumišęs. Radialinis pulsas silpnas, oda blyški, šalta, drėgna. (AVPU V)","k":"Ką C garsiai praneša A?"},{"n":"2 klausimas","v":{"hr":130,"sys":88,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"Išorinio kraujavimo nėra, dubuo stabilus. Kraujo grupė nustatyta, veikia 2 PVK. A klausia C, kas skiriama.","k":"Kuris planas atitinka žalos kontrolės gaivinimą?"},{"n":"3 klausimas","v":{"hr":112,"sys":92,"dia":55,"spo2":97,"rr":16,"temp":36.6},"p":"Perpiltas pirmasis kraujo vienetas. Sąmonė gerėja, radialinis pulsas čiuopiamas. Chirurginė kontrolė dar nepasiekta.","k":"Kas dabar teisinga?"}]},{"id":"s5","src":"ETC","pav":"Kritimas nuo šarvuočio","tema":"Galva","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":100,"dia":60,"spo2":89,"rr":10,"temp":36.6},"p":"Karys nukrito nuo šarvuočio, kaktos žaizda. Kitų sužalojimų ir šoko požymių nerasta. Kvėpuoja paviršutiniškai. (GKS 9)","k":"Kurie tikslai svarbiausi?"},{"n":"2 klausimas","v":{"hr":90,"sys":100,"dia":60,"spo2":95,"rr":10,"temp":36.6},"p":"Pacientas tampa neramus, planuojama sedacija ir RSI. Komanda ruošia vaistus. (GKS 8)","k":"Ką A privalo padaryti prieš sedaciją?"},{"n":"3 klausimas","v":{"hr":90,"sys":118,"dia":70,"spo2":97,"rr":10,"temp":36.6},"p":"Po 10 min, dar prieš sedaciją, kairysis vyzdys išsiplėtęs ir nereaguoja į šviesą, GKS sumažėjo iki 6. AKS ir SpO₂ tiksluose. (GKS 6)","k":"Kaip reaguoja A?"}]},{"id":"s6","src":"ETC","pav":"Šarvuočio gaisras","tema":"Nudegimai","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":95,"rr":24,"temp":36.6},"p":"Karys ištrauktas iš degančio šarvuočio. Veido nudegimai, apdegę nosies plaukai, suodžiai skrepliuose, balsas užkimęs. Kol kas kalba. (AVPU A)","k":"Kaip A valdo kvėpavimo takus?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":95,"rr":24,"temp":36.6},"p":"Kvėpavimo takai užtikrinti. Veidas paraudęs, be pūslių; visame liemens priekyje (krūtinė ir pilvas) ir visoje dešinėje rankoje pūslės ir balti plotai.","k":"Kaip apskaičiuojamas nudegimo plotas?"},{"n":"3 klausimas","v":{"hr":118,"sys":110,"dia":70,"spo2":95,"rr":24,"temp":35.1},"p":"Nudegimai ~27 % KPP, vėsinti vandeniu 20 min. Pacientas dreba, centrinė temperatūra krenta.","k":"Kas toliau?"}]},{"id":"s7","src":"ETC","pav":"Šautinė į krūtinę","tema":"Kita","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Iš pozicijų atvežamas karys su šautine žaizda krūtinėje. A 5 s apžiūroje: nereaguoja, kvėpuoja agoniškai, centrinio pulso nėra. (AVPU U)","k":"Ką skelbia A?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"C įvedė IO, perpilamas šildytas kraujas, A ventiliuoja 100 % O₂. B nustato, kad dešinėje kvėpavimo garsai susilpnėję. (AVPU U)","k":"Kaip B atlieka dekompresiją?"},{"n":"3 klausimas","v":{"hr":140,"sys":74,"dia":40,"spo2":97,"rr":16,"temp":36.6},"p":"Po abipusės dekompresijos ir kraujo perpylimo atsirado centrinis pulsas.","k":"Koks tolesnis planas?"}]},{"id":"s8","src":"ETC","pav":"Apvirtęs visureigis: dubuo","tema":"Šokas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":128,"sys":86,"dia":52,"spo2":97,"rr":16,"temp":36.6},"p":"Karys po karinio visureigio apvirtimo, skundžiasi dubens skausmu. Išorinio kraujavimo nėra, bet yra šoko požymių. B pradeda dubens vertinimą. (AVPU V)","k":"Kaip B vertina dubenį?"},{"n":"2 klausimas","v":{"hr":134,"sys":82,"dia":50,"spo2":97,"rr":16,"temp":36.6},"p":"Dubuo nestabilus, kraujas šlaplės angoje. Kišenės ištuštintos, pacientas ant nugaros.","k":"Kaip uždedamas dubens diržas?"},{"n":"3 klausimas","v":{"hr":138,"sys":78,"dia":46,"spo2":97,"rr":16,"temp":36.6},"p":"Diržas uždėtas, perpilti 2 kraujo vienetai, TXA ir kalcis skirti. Šokas nepraeina.","k":"Ką daro komanda?"}]},{"id":"s9","src":"ETC","pav":"Blauzdos lūžis ir skausmas","tema":"Kita","lygis":"","st":[{"n":"1 klausimas","v":{"hr":118,"sys":96,"dia":60,"spo2":97,"rr":16,"temp":36.6},"p":"Atviras blauzdos lūžis po minos skeveldros, kraujavimas sustabdytas, galūnė dar neįtvarkyta. Skausmas 8/10, yra šoko požymių. A skiria analgeziją. (AVPU A)","k":"Kuris sprendimas teisingas?"},{"n":"2 klausimas","v":{"hr":118,"sys":102,"dia":64,"spo2":97,"rr":16,"temp":36.6},"p":"Po 5 min skausmas 5/10, atsirado nistagmas. Kvėpavimas ir AKS stabilūs.","k":"Ar kartoti ketamino dozę dabar?"},{"n":"3 klausimas","v":{"hr":118,"sys":102,"dia":64,"spo2":96,"rr":16,"temp":36.6},"p":"Pacientą pradeda pykinti, atsiranda seilėtekis. Sąmonė ta pati. (AVPU A)","k":"Ką daryti?"}]},{"id":"s10","src":"ETC","pav":"Nuo pirminės iki perdavimo","tema":"Kita","lygis":"","st":[{"n":"1 klausimas","v":{"hr":104,"sys":112,"dia":70,"spo2":97,"rr":16,"temp":34.6},"p":"Vyksta pirminė apžiūra: masyvaus kraujavimo nėra, kvėpavimo takai laisvi. Karys po apšaudymo ištrauktas iš vandens griovio, drabužiai šlapi, dreba.","k":"Kaip valdoma hipotermija?"},{"n":"2 klausimas","v":{"hr":132,"sys":78,"dia":45,"spo2":97,"rr":16,"temp":34.6},"p":"Antrinės apžiūros metu A tikrina veidą. Rašytojas praneša, kad AKS krinta, pacientas tampa mieguistas. (AVPU V)","k":"Ką daro A?"},{"n":"3 klausimas","v":{"hr":102,"sys":104,"dia":66,"spo2":97,"rr":16,"temp":34.6},"p":"Pacientas stabilizuotas, perkeliamas į operacinę. Ant dilbio – turniketas, veikia 2 PVK, skirti vaistai.","k":"Kaip atliekamas perdavimas?"}]},{"id":"s11","src":"ETC","pav":"Kirkšnis po skeveldros","tema":"Kraujavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":128,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Patrulį apšaudė minosvaidžiais. Karys atvežamas į Role 1 su skeveldros žaizda dešinėje kirkšnyje – iš jos gausiai bėga ryškiai raudonas kraujas. A paskelbė „Masyvus kraujavimas“. (AVPU V)","k":"Kaip B ir C stabdo kraujavimą?"},{"n":"2 klausimas","v":{"hr":126,"sys":96,"dia":62,"spo2":97,"rr":16,"temp":36.6},"p":"Žaizda sutamponuota hemostatine marle, C spaudžia nepertraukiamai 3 min. Atleidus spaudimą per marlę vėl sunkiasi kraujas.","k":"Ką daryti dabar?"},{"n":"3 klausimas","v":{"hr":124,"sys":94,"dia":60,"spo2":97,"rr":16,"temp":36.6},"p":"Po pakartotinio tamponavimo kraujavimas sustojo. C paruošė jungčių turniketą (SAM JT).","k":"Kaip uždedamas jungčių turniketas?"}]},{"id":"s12","src":"ETC","pav":"Kaklo žaizda po SSU","tema":"Kraujavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":122,"sys":120,"dia":78,"spo2":97,"rr":24,"temp":36.6},"p":"Kolonos priekinė mašina užvažiavo ant SSU. Karys atvežamas su skeveldros žaizda kairėje kaklo pusėje – kraujas srūva pro pridėtą tvarstį. Karys sumišęs, akis atmerkia tik kalbinamas. (AVPU V)","k":"Ką pirmiausia skelbia A?"},{"n":"2 klausimas","v":{"hr":116,"sys":102,"dia":66,"spo2":96,"rr":24,"temp":36.6},"p":"Žaizda sutamponuota hemostatine marle ir spausta 3 min – kraujavimas sustojo. Reikia uždėti spaudžiamąjį tvarstį.","k":"Kaip tvarstomas kaklas?"},{"n":"3 klausimas","v":{"hr":124,"sys":90,"dia":58,"spo2":96,"rr":24,"temp":36.6},"p":"C nustatė kraujo grupę EldonCard kortele – B Rh−. Šoko požymiai išlieka, A paskyrė eritrocitų.","k":"Kurių grupių eritrocitus galima perpilti?"}]},{"id":"s13","src":"ETC","pav":"Abi kojos po minos","tema":"Kraujavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":128,"sys":94,"dia":58,"spo2":97,"rr":16,"temp":36.6},"p":"Patrulio karys užlipo ant priešpėstinės minos. Atvežamas su dviem kovos mediko uždėtais turniketais ant kelnių: kairėje – blauzdos amputacija, dešinėje – gili blauzdos žaizda. Laikas užrašytas prieš 35 min. (AVPU V)","k":"Kaip komanda elgiasi su turniketais?"},{"n":"2 klausimas","v":{"hr":130,"sys":92,"dia":56,"spo2":97,"rr":16,"temp":36.6},"p":"Dešinėje kojoje naujas turniketas uždėtas ant odos 5–8 cm virš žaizdos. Kraujavimas sustojo, bet B dar čiuopia pėdos pulsą.","k":"Ką daryti?"},{"n":"3 klausimas","v":{"hr":134,"sys":84,"dia":50,"spo2":97,"rr":16,"temp":36.6},"p":"Kraujavimas sustabdytas, bet C praneša: hemoraginis šokas – taip. Kario žetone nurodyta grupė A Rh+, EldonCard dar neatlikta. (AVPU V)","k":"Kokį kraują perpilti?"}]},{"id":"s14","src":"ETC","pav":"Nepavykęs PVK","tema":"Šokas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":132,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"Artilerijos skeveldros sužeidė karį į pilvą ir dešinę blauzdą (atviras lūžis). Rankos šaltos, venų nesimato. C per 90 s du kartus nesėkmingai bandė įvesti PVK. (AVPU V)","k":"Ką daro C?"},{"n":"2 klausimas","v":{"hr":134,"sys":84,"dia":52,"spo2":97,"rr":16,"temp":36.6},"p":"C pasiruošė IO grąžtą, 15 G adatą ir užpildytą liniją. Dešinė blauzda lūžusi.","k":"Kur ir kaip durti?"},{"n":"3 klausimas","v":{"hr":132,"sys":82,"dia":50,"spo2":97,"rr":16,"temp":36.6},"p":"IO įvesta, aspiruotas kaulų čiulpų turinys. Prijungtas šildytas kraujas, bet jis savaime teka labai lėtai.","k":"Kas teisinga?"}]},{"id":"s15","src":"ETC","pav":"Transfuzija lauko punkte","tema":"Šokas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":128,"sys":86,"dia":52,"spo2":97,"rr":16,"temp":36.6},"p":"Karys sužeistas drono numesta granata į šlaunį. Žaizda sutamponuota, C praneša: hemoraginis šokas – taip. Iš transportavimo dėžės ką tik išimtas O grupės kraujo vienetas. (AVPU V)","k":"Kas turi būti užtikrinta pradedant perpylimą?"},{"n":"2 klausimas","v":{"hr":118,"sys":94,"dia":58,"spo2":97,"rr":16,"temp":36.6},"p":"Pirmasis vienetas perpiltas per kairės rankos 18 G PVK, linija laisva. Dešinės rankos PVK vieta paburkusi, pabalusi ir vėsi. A paskiria kalcį.","k":"Kaip skiriamas kalcis?"},{"n":"3 klausimas","v":{"hr":136,"sys":78,"dia":46,"spo2":97,"rr":28,"temp":38.6},"p":"Lašinant antrąjį vienetą karys pradeda dusti, skundžiasi nugaros skausmu, karščiuoja, AKS krenta; kateterio maiše – rausvas šlapimas.","k":"Ką daro C?"}]},{"id":"s17","src":"ETC","pav":"Pavėluota konversija","tema":"Kraujavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":94,"sys":128,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Dėl dronų grėsmės evakuacija užtruko: karys su skeveldros žaizda dilbyje atvežamas po 3,5 val. Turniketas ant žasto uždėtas ant rankovės. Pirminė apžiūra baigta – šoko nėra. (AVPU A)","k":"Kas teisinga dėl turniketo konversijos?"},{"n":"2 klausimas","v":{"hr":92,"sys":126,"dia":76,"spo2":97,"rr":16,"temp":36.6},"p":"Naujas turniketas uždėtas ant odos 5–8 cm virš žaizdos, senasis lėtai atleistas. Žaizda sutamponuota hemostatine marle, spausta 3 min, uždėtas spaudžiamasis tvarstis.","k":"Kaip atleidžiamas turniketas?"},{"n":"3 klausimas","v":{"hr":88,"sys":112,"dia":70,"spo2":97,"rr":16,"temp":36.6},"p":"Po 10 min monitoriuje atsiranda EKG pokyčių, įtariama hiperkalemija. Tvarstis sausas, kraujavimo nėra.","k":"Ką skiria C gydytojo nurodymu?"}]},{"id":"s18","src":"ETC","pav":"Žiemos operacija","tema":"Šokas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":126,"sys":90,"dia":56,"spo2":97,"rr":16,"temp":34.2},"p":"Žiemos operacija, −15 °C. Karys sužeistas minosvaidžio skeveldromis į šlaunį ir pilvą, 50 min vežtas atviru visureigiu; uniforma šlapia nuo sniego ir kraujo. Šlaunies turniketas veikia. (AVPU V)","k":"Kuris teiginys teisingas?"},{"n":"2 klausimas","v":{"hr":130,"sys":86,"dia":52,"spo2":97,"rr":16,"temp":34.0},"p":"Šlapi drabužiai nuimti. Visureigyje liko šalti kristaloidai, punkte – kraujo komponentai transportavimo dėžėje. A klausia C dėl skysčių.","k":"Kas teisinga?"},{"n":"3 klausimas","v":{"hr":118,"sys":92,"dia":58,"spo2":97,"rr":16,"temp":33.1},"p":"Perpilti 2 šildyti vienetai, skirta TXA ir kalcis, uždėta priverstinio oro šildymo antklodė. Karys mieguistas, drebulys silpnėja. (AVPU V)","k":"Ką daryti toliau?"}]},{"id":"s19","src":"ETC","pav":"Apvirtęs šarvuotis","tema":"Šokas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":132,"sys":84,"dia":50,"spo2":97,"rr":16,"temp":36.6},"p":"Pratybose šarvuotis apvirto į griovį, karys buvo prispaustas per dubenį ir trenkėsi galva. Įgula uždėjo dubens diržą. B pastebi, kad diržas yra ant klubakaulių keterų. (AVPU V, GKS 11)","k":"Ką daro B ir C?"},{"n":"2 klausimas","v":{"hr":134,"sys":82,"dia":48,"spo2":97,"rr":16,"temp":36.6},"p":"Diržas pataisytas, perpilamas šildytas kraujas. C siūlo apversti karį ant šono ir apžiūrėti nugarą prieš e-FAST.","k":"Ką sprendžia A?"},{"n":"3 klausimas","v":{"hr":120,"sys":96,"dia":60,"spo2":97,"rr":16,"temp":36.6},"p":"Skirta TXA ir kalcis. A primena, kad karys trenkėsi galva ir GKS 11. Chirurginė kontrolė dar nepasiekta. (GKS 11)","k":"Koks AKS tikslas?"}]},{"id":"s20","src":"ETC","pav":"Šautinė į pilvą","tema":"Šokas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":132,"sys":88,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"Karys peršautas į pilvą žemiau šarvinės liemenės krašto. Dėl artilerijos ugnies evakuacija užtruko – traumos laikas užrašytas prieš 2 val. 40 min. C praneša: hemoraginis šokas – taip. (AVPU V)","k":"Ar skirti TXA?"},{"n":"2 klausimas","v":{"hr":134,"sys":86,"dia":52,"spo2":97,"rr":16,"temp":36.6},"p":"Punkte yra šaltai laikyto mažo titro O grupės pilno kraujo, plazmos ir eritrocitų. A klausia, ką perpilti pirmiausia.","k":"Kas perpilama pirmiausia?"},{"n":"3 klausimas","v":{"hr":138,"sys":80,"dia":48,"spo2":97,"rr":16,"temp":36.6},"p":"Pilnas kraujas baigėsi, šokas tebėra, evakuacija į chirurgiją vėluoja. Kuopoje yra iš anksto ištirtų O grupės donorų ir savanorių, kurių grupė žinoma tik iš žetono.","k":"Kas teisinga?"}]},{"id":"s21","src":"ETC","pav":"Skeveldros veide","tema":"Kvėpavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":86,"rr":30,"temp":36.6},"p":"Minosvaidžio sviedinio skeveldros sužalojo patrulio kario veidą. A 5 s apžiūroje: karys sujaudintas, girdimas burbuliavimas, burnoje kraujas ir išmušti dantys. (AVPU A)","k":"Ką A paskelbia?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":87,"rr":30,"temp":36.6},"p":"Kaklo trauma neatmesta, kitas narys laiko MILS. Burnoje krešuliai ir keli išmušti dantys.","k":"Kaip A išvalo burną?"},{"n":"3 klausimas","v":{"hr":122,"sys":120,"dia":78,"spo2":83,"rr":30,"temp":36.6},"p":"Apatinis žandikaulis lūžęs, matomi ir vidurinės veido dalies lūžiai. Kraujas į burną teka nuolat, nors siurbiama; stumiant žandikaulį obstrukcija nemažėja.","k":"Kas toliau?"}]},{"id":"s22","src":"ETC","pav":"Be sąmonės po sprogimo","tema":"Kvėpavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":91,"rr":10,"temp":36.6},"p":"Šalia šarvuočio sprogo SSU, karį nubloškė kelis metrus. Atvežtas be kaklo įtvaro: reaguoja tik į skausmą, knarkia, ant pakaušio kraujosruva. (AVPU P)","k":"Kaip atveriami kvėpavimo takai?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":93,"rr":10,"temp":36.6},"p":"Kol žandikaulis laikomas, takai laisvi, bet jį atleidus knarkimas grįžta. Vėmimo reflekso nėra. (AVPU P)","k":"Kaip A parenka ir įveda orofaringinį vamzdelį?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":95,"rr":6,"temp":36.6},"p":"OPA toleruojamas, uždėta kaukė su rezervuaru 15 l/min. Kvėpavimas paviršinis ir retas, pulsoksimetras rodo gerą SpO₂. (AVPU P)","k":"Ką daro A?"}]},{"id":"s23","src":"ETC","pav":"Nepavykusi intubacija – CICO","tema":"Kvėpavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":89,"rr":28,"temp":36.6},"p":"Drono numestos granatos skeveldros sužalojo kario apatinę veido dalį ir kaklą; kaklas tinsta. Kaklo įtvaras nedėtas – jis spaustų tinstančius audinius; galvą laiko MILS. Gydytojas nusprendė intubuoti RSI būdu. (AVPU V)","k":"Kas būtina prieš indukciją?"},{"n":"2 klausimas","v":{"hr":124,"sys":120,"dia":78,"spo2":84,"rr":28,"temp":36.6},"p":"Po trijų intubacijos bandymų vamzdelio įvesti nepavyko. SpO₂ krenta.","k":"Ką daryti toliau?"},{"n":"3 klausimas","v":{"hr":52,"sys":120,"dia":78,"spo2":71,"rr":28,"temp":36.6},"p":"Nei kauke, nei laringine kauke oksigenuoti nepavyksta – paskelbtas CICO. Dėl tinimo krikotiroidinė membrana nečiuopiama.","k":"Kaip atliekama krikotiroidotomija?"}]},{"id":"s24","src":"ETC","pav":"Masyvus hemotoraksas","tema":"Krūtinė","lygis":"","st":[{"n":"1 klausimas","v":{"hr":132,"sys":84,"dia":52,"spo2":90,"rr":30,"temp":36.6},"p":"Artilerijos sviedinio skeveldra pataikė kariui į dešinį krūtinės šoną po liemene. B: dešinėje susilpnėję kvėpavimo garsai, perkutuojant duslus garsas, oda blyški ir šalta.","k":"Ką B praneša A?"},{"n":"2 klausimas","v":{"hr":132,"sys":88,"dia":56,"spo2":91,"rr":30,"temp":36.6},"p":"A nurodo drenuoti. C įvedė 2 PVK, perpilami kraujo komponentai. Gydytojas B ruošiasi pleuros drenavimui.","k":"Kaip įvedamas pleuros drenas?"},{"n":"3 klausimas","v":{"hr":128,"sys":80,"dia":50,"spo2":91,"rr":30,"temp":36.6},"p":"Atleidus spaustuką iš karto išbėgo 1600 ml kraujo. AKS tebėra žemas.","k":"Koks tolesnis veiksmas?"}]},{"id":"s25","src":"ETC","pav":"Nestabili krūtinės ląsta","tema":"Krūtinė","lygis":"","st":[{"n":"1 klausimas","v":{"hr":104,"sys":128,"dia":80,"spo2":94,"rr":24,"temp":36.6},"p":"Per pratybas apvirto šarvuotis; vairuotojas kairiu šonu trenkėsi į liuko kraštą. B: kairėje kraujosruvos, krepitacija, poodinė emfizema, paradoksinių judesių nematyti.","k":"Kaip B vertina radinius?"},{"n":"2 klausimas","v":{"hr":104,"sys":128,"dia":80,"spo2":87,"rr":34,"temp":36.6},"p":"Po 20 min kairės krūtinės segmentas įkvepiant įdumba, karys išsekęs, kalba tik trumpomis frazėmis. Kaukė su rezervuaru 15 l/min. (AVPU A)","k":"Ką sprendžia A?"},{"n":"3 klausimas","v":{"hr":138,"sys":76,"dia":44,"spo2":80,"rr":34,"temp":36.6},"p":"Karys intubuotas ir ventiliuojamas. Po kelių minučių staiga krenta SpO₂ ir AKS, kairėje negirdėti kvėpavimo garsų.","k":"Ką daro B (gydytojas)?"}]},{"id":"s26","src":"ETC","pav":"Pneumotoraksas po evakuacijos","tema":"Krūtinė","lygis":"","st":[{"n":"1 klausimas","v":{"hr":98,"sys":124,"dia":78,"spo2":95,"rr":22,"temp":36.6},"p":"Minos sprogimo banga nubloškė karį į šarvuočio bortą. Po 40 min evakuacijos atvežtas į Role 1; B pirminėje apžiūroje ryškių krūtinės radinių neranda, hemodinamika stabili, stuburo ar dubens sužalojimo požymių nėra.","k":"Ką B daro prieš e-FAST?"},{"n":"2 klausimas","v":{"hr":98,"sys":120,"dia":76,"spo2":92,"rr":28,"temp":36.6},"p":"Po 15 min karys skundžiasi dusuliu, kvėpuoja dažniau. e-FAST: kairėje nėra pleuros slydimo ir B linijų, dešinėje slydimas yra.","k":"Ką reiškia radinys?"},{"n":"3 klausimas","v":{"hr":98,"sys":120,"dia":76,"spo2":97,"rr":18,"temp":36.6},"p":"Įvestas pleuros drenas, prijungta povandeninė drenažo sistema. Karys ruošiamas tolesnei evakuacijai.","k":"Kaip elgtis su drenažo sistema pervežant?"}]},{"id":"s27","src":"ETC","pav":"Įkvėpimo trauma","tema":"Kvėpavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":112,"sys":120,"dia":78,"spo2":99,"rr":24,"temp":36.6},"p":"Iš degančios pėstininkų kovos mašinos ištrauktas šaulys. Veidas apdegęs, nosies plaukai apsvilę, skrepliuose suodžiai, balsas užkimęs. (AVPU A)","k":"Kaip A skiria deguonį?"},{"n":"2 klausimas","v":{"hr":112,"sys":120,"dia":78,"spo2":95,"rr":30,"temp":36.6},"p":"Po 10 min užkimimas stiprėja, atsiranda stridoras, veidas tinsta.","k":"Koks kvėpavimo takų planas?"},{"n":"3 klausimas","v":{"hr":112,"sys":120,"dia":78,"spo2":98,"rr":30,"temp":35.8},"p":"Šaulys intubuotas. Antrinėje apžiūroje B randa II–III laipsnio nudegimus ant krūtinės ir pečių.","k":"Kaip B sutvarko krūtinės nudegimus?"}]},{"id":"s28","src":"ETC","pav":"Vėmimas gulint ant nugaros","tema":"Kvėpavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":89,"rr":16,"temp":36.6},"p":"Per pratybas karys nukrito nuo sunkvežimio kėbulo ant galvos. Guli ant nugaros su kaklo įtvaru ir blokais, staiga pradeda vemti, girdimas burbuliavimas. (AVPU P, GKS 8)","k":"Kaip komanda saugo kvėpavimo takus?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":93,"rr":16,"temp":36.6},"p":"Vėmalai atsiurbti, bet GKS 7 – kvėpavimo takų jis neapsaugo. Gydytojas ruošia RSI; karys vis dar periodiškai vemia. (GKS 7)","k":"Kas teisinga dėl aspiracijos rizikos?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":96,"rr":16,"temp":36.6},"p":"Vamzdelis įvestas laikant MILS. Gydytojas tikrina jo padėtį.","k":"Kas patikimiausiai atmeta stemplės intubaciją?"}]},{"id":"s29","src":"ETC","pav":"Kulka į šarvinę liemenę","tema":"Krūtinė","lygis":"","st":[{"n":"1 klausimas","v":{"hr":132,"sys":86,"dia":58,"spo2":84,"rr":36,"temp":36.6},"p":"Snaiperio kulka pataikė į kario šarvinės liemenės plokštę dešinėje. Role 1 budi tik kovos medikas ir slaugytoja, gydytojas dar neatvyko. Dešinėje negirdėti kvėpavimo garsų, dėžinis garsas, kaklo venos išsiplėtusios.","k":"Ką daro B (kovos medikas)?"},{"n":"2 klausimas","v":{"hr":132,"sys":86,"dia":58,"spo2":82,"rr":36,"temp":36.6},"p":"B paruošė adatą ir ieško dūrio vietos dešinėje.","k":"Kaip atliekama adatinė dekompresija?"},{"n":"3 klausimas","v":{"hr":132,"sys":84,"dia":54,"spo2":85,"rr":34,"temp":36.6},"p":"Oro švilpimo B negirdėjo, bet SpO₂ ir AKS trumpam pagerėjo. Po 10 min būklė vėl blogėja, gydytojas dar kelyje.","k":"Ką daro B?"}]},{"id":"s30","src":"ETC","pav":"Neefektyvi ventiliacija","tema":"Kvėpavimas","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":86,"rr":6,"temp":36.6},"p":"Drono granata sužeidė kario galvą; kvėpavimas nepakankamas, įdėtas OPA. Kovos medikas vienas ventiliuoja „C–E“ būdu: krūtinė beveik nekyla, girdimas oro nuotėkis pro kaukę. (AVPU U)","k":"Kaip pagerinti ventiliaciją?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":84,"rr":6,"temp":36.6},"p":"Ir dviese ventiliacija lieka neefektyvi, intubuojančio gydytojo nėra. A nusprendžia dėti laringinę kaukę (i-gel).","k":"Kas teisinga dedant laringinę kaukę?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":82,"rr":6,"temp":36.6},"p":"Laringinė kaukė įdėta, bet ventiliuojant girdimas didelis nuotėkis, krūtinė kyla silpnai, pučiasi skrandis.","k":"Ką tai reiškia ir ką daryti?"}]},{"id":"s31","src":"ETC","pav":"Vyzdžiai po artilerijos sprogimo","tema":"Galva","lygis":"","st":[{"n":"1 klausimas","v":{"hr":128,"sys":86,"dia":50,"spo2":89,"rr":16,"temp":36.6},"p":"Artilerijos sviedinys sprogo prie apkaso, sprogimo banga karį nubloškė į apkaso sienelę. Į Role 1 atvežtas mieguistas, šlaunyje – skeveldros žaizda, kraujavimas sustabdytas spaudžiamuoju tvarsčiu. Oda blyški, šalta. (AVPU V)","k":"Kaip A turi aiškinti sutrikusią sąmonę?"},{"n":"2 klausimas","v":{"hr":94,"sys":116,"dia":72,"spo2":96,"rr":16,"temp":36.6},"p":"Po kraujo komponentų ir deguonies AKS ir SpO₂ pasiekė tikslus, šoko požymių nebėra. GKS 10, kaklas įtvare, karys guli horizontaliai. (GKS 10)","k":"Kokia padėtis ir priemonės dabar tinkamiausios?"},{"n":"3 klausimas","v":{"hr":62,"sys":122,"dia":70,"spo2":98,"rr":16,"temp":36.6},"p":"Karys intubuotas ir ventiliuojamas. Po 10 min dešinysis vyzdys išsiplėtęs ir nereaguoja į šviesą, atsirado patologinė laikysena. B ventiliuoja dažnai, EtCO₂ 26 mm Hg.","k":"Ką daro A?"}]},{"id":"s32","src":"ETC","pav":"Skeveldra akyje","tema":"Galva","lygis":"","st":[{"n":"1 klausimas","v":{"hr":96,"sys":128,"dia":80,"spo2":97,"rr":16,"temp":36.6},"p":"Į apkasą įkrito granata, numesta nuo drono. Karys atvežtas į Role 1 sąmoningas, iš dešinės akies kyšo smulki skeveldra, vokai patinę. B ruošia spaudžiamąjį tvarstį ant akių. (AVPU A)","k":"Kaip tvarkoma sužeista akis?"},{"n":"2 klausimas","v":{"hr":96,"sys":128,"dia":80,"spo2":98,"rr":16,"temp":36.6},"p":"Antrinėje apžiūroje A apžiūri akis. Kairė akis atrodo sveika, dešinės akies patinusių vokų karys pats neatmerkia. (AVPU A)","k":"Kaip A įvertina regėjimą?"},{"n":"3 klausimas","v":{"hr":92,"sys":124,"dia":78,"spo2":98,"rr":16,"temp":36.6},"p":"Skydelis pritvirtintas. Karį pykina, jis du kartus vėmė ir gerti negali. Alergijų neturi. (AVPU A)","k":"Kokį antibiotiką skirti?"}]},{"id":"s33","src":"ETC","pav":"Smūgis šautuvo buože","tema":"Galva","lygis":"","st":[{"n":"1 klausimas","v":{"hr":112,"sys":120,"dia":78,"spo2":90,"rr":26,"temp":36.6},"p":"Valant pastatą per operaciją kariui į veidą smogė priešininkas šautuvo buože. Atvežtas į Role 1: iš nosies ir į burną gausiai teka kraujas, girdisi gurgimas, vidurinė veido dalis judri. (AVPU V)","k":"Kas daroma pirmiausia?"},{"n":"2 klausimas","v":{"hr":104,"sys":108,"dia":66,"spo2":97,"rr":26,"temp":36.6},"p":"Karys intubuotas. A antrinėje apžiūroje nustato, kad veido kaulai nestabilūs, iš nosies tebekraujuoja.","k":"Ką A nurodo B prieš nosies tamponadą?"},{"n":"3 klausimas","v":{"hr":108,"sys":104,"dia":64,"spo2":97,"rr":26,"temp":36.6},"p":"Lūžgaliai stabilizuoti. B ruošia užpakalinę tamponadą – komercinio baliono nėra, yra 12 Fr Foley kateteris.","k":"Kaip B atlieka užpakalinę tamponadą?"}]},{"id":"s34","src":"ETC","pav":"Stuburo trauma po kritimo","tema":"Kita","lygis":"","st":[{"n":"1 klausimas","v":{"hr":88,"sys":118,"dia":74,"spo2":96,"rr":16,"temp":36.6},"p":"Per naktinę operaciją karys nukrito nuo šarvuočio stogo ant betono. Atneštas į Role 1 be kaklo imobilizacijos, skundžiasi kaklo skausmu ir rankų dilgčiojimu. (AVPU A)","k":"Kaip stabilizuojamas kaklas atvykus?"},{"n":"2 klausimas","v":{"hr":62,"sys":102,"dia":60,"spo2":94,"rr":24,"temp":36.6},"p":"A pastebi, kad karys kvėpuoja pilvu, oda šilta, rankų jėga silpnėja, B mato priapizmą.","k":"Ką rodo šie požymiai?"},{"n":"3 klausimas","v":{"hr":66,"sys":106,"dia":64,"spo2":95,"rr":24,"temp":36.6},"p":"Karys guli ant stuburo lentos, kaklas įtvare. Nugara dar neapžiūrėta, hemodinamika stabili; KT nebus, A nusprendžia nugarą apžiūrėti.","k":"Kaip teisingai apžiūrėti nugarą?"}]},{"id":"s35","src":"ETC","pav":"Atviras šlaunies lūžis","tema":"Kita","lygis":"","st":[{"n":"1 klausimas","v":{"hr":124,"sys":94,"dia":60,"spo2":97,"rr":16,"temp":36.6},"p":"Patrulio metu šalia kario sprogo minosvaidžio mina, skeveldra kliudė šlaunį. Šlaunyje atviras lūžis, išorinis kraujavimas sustabdytas tvarsčiu, kitų žaizdų nerasta. Šlaunis tinsta, karys blyškus. (AVPU A)","k":"Kaip vertinti šią hemodinamiką?"},{"n":"2 klausimas","v":{"hr":108,"sys":106,"dia":66,"spo2":97,"rr":16,"temp":36.6},"p":"Gaivinimas pradėtas, kraujavimas kontroliuojamas. Antrinėje apžiūroje C imasi šlaunies, B rankomis stabilizuoja lūžio vietą. Iš žaizdos kyšo kaulas.","k":"Kaip C imobilizuoja galūnę?"},{"n":"3 klausimas","v":{"hr":102,"sys":110,"dia":68,"spo2":97,"rr":16,"temp":36.6},"p":"Įtvaras uždėtas. Tikrinant PMS paaiškėja, kad pėdos pulso, kuris prieš įtvarą buvo, nebeapčiuopiama.","k":"Ką daro C?"}]},{"id":"s36","src":"ETC","pav":"Praleista nugaros žaizda","tema":"Kita","lygis":"","st":[{"n":"1 klausimas","v":{"hr":136,"sys":78,"dia":44,"spo2":97,"rr":16,"temp":36.6},"p":"Šalia apkaso sprogo dronas kamikadzė. Karys atvežtas su šoko požymiais, B įtaria dubens lūžį, kartu su C uždėtas dubens diržas. C ruošiasi su B versti karį nugaros apžiūrai prieš e-FAST. (AVPU V)","k":"Ką sprendžia A?"},{"n":"2 klausimas","v":{"hr":98,"sys":112,"dia":70,"spo2":97,"rr":16,"temp":36.6},"p":"Po gaivinimo būklė stabilizavosi, pradedama antrinė apžiūra. Rašytojas primena, kad nugara neapžiūrėta. A sako: „Nugarą apžiūrės Role 2.“ (AVPU A, GKS 15)","k":"Kas teisinga?"},{"n":"3 klausimas","v":{"hr":98,"sys":110,"dia":68,"spo2":92,"rr":28,"temp":36.6},"p":"Paverčiant rąstu B tarp menčių randa nedidelę skeveldros žaizdą, kuri įkvepiant šnypščia. Kvėpavimo dažnis didėja.","k":"Ką daro B?"}]},{"id":"s37","src":"ETC","pav":"Sumišęs karys pratybose","tema":"Galva","lygis":"","st":[{"n":"1 klausimas","v":{"hr":84,"sys":132,"dia":80,"spo2":97,"rr":16,"temp":36.6},"p":"Per lauko pratybas karys nukrito nuo kliūčių ruožo sienelės ir trenkėsi galva. Role 1: atsimerkia tik kalbinamas, atsako sumišęs, bet komandas vykdo. (AVPU V)","k":"Kokia kario GKS?"},{"n":"2 klausimas","v":{"hr":96,"sys":128,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Karys visą parą žygiavo su pilna ekipuote, beveik nevalgė, dabar prakaituotas ir drebančiomis rankomis. A rašo „sumišimas dėl galvos smūgio“. (GKS 13)","k":"Ką būtina padaryti prieš tokią išvadą?"},{"n":"3 klausimas","v":{"hr":96,"sys":128,"dia":78,"spo2":96,"rr":16,"temp":36.6},"p":"Gliukozė normali. Antrinėje apžiūroje A randa mėlynes už ausų, kraujosruvas aplink abi akis, iš nosies sunkiasi skaidrus skystis. GKS nekinta. (GKS 13)","k":"Kaip A vertina radinius?"}]},{"id":"s38","src":"ETC","pav":"Akiduobė po SSU","tema":"Galva","lygis":"","st":[{"n":"1 klausimas","v":{"hr":98,"sys":126,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Kolonoje po šarvuočiu sprogo savadarbis sprogmuo (SSU), vairuotojas susitrenkė veidą. Antrinėje apžiūroje kairysis akies obuolys išsikišęs, akiduobė įtempta, judesiai riboti, karys sako, kad kaire akimi mato vis blogiau. (AVPU A)","k":"Kas įtariama ir ką daryti?"},{"n":"2 klausimas","v":{"hr":102,"sys":126,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Kompetentingas komandos narys perkirpo lateralinį voko kampą iki kaulinio akiduobės krašto, tačiau akiduobė tebėra įtempta. (AVPU A)","k":"Koks kitas žingsnis?"},{"n":"3 klausimas","v":{"hr":94,"sys":122,"dia":76,"spo2":97,"rr":16,"temp":36.6},"p":"Perkirpus apatinę kojytę vokas laisvas, akiduobė minkštesnė. Karys ruošiamas evakuacijai. (AVPU A)","k":"Kaip stebima akis toliau?"}]},{"id":"s39","src":"ETC","pav":"Antrinė apžiūra prieš evakuaciją","tema":"Kita","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":124,"dia":76,"spo2":98,"rr":16,"temp":36.6},"p":"Per pratybas apvirto karinis visureigis. Kulkosvaidininkas Role 1: pirminė apžiūra baigta, gyvybei pavojingų būklių nerasta, būklė stabili. Evakuacija – po 40 min. (AVPU A, GKS 15)","k":"Kaip organizuojama antrinė apžiūra?"},{"n":"2 klausimas","v":{"hr":90,"sys":122,"dia":74,"spo2":98,"rr":16,"temp":36.6},"p":"A renka anamnezę. Karys kalba aiškiai, pasakoja, kaip apvirto visureigis. (GKS 15)","k":"Ką A turi išsiaiškinti?"},{"n":"3 klausimas","v":{"hr":92,"sys":120,"dia":74,"spo2":98,"rr":16,"temp":36.6},"p":"C randa deformuotą, skausmingą dešinį dilbį be žaizdos, PMS geri. Ant riešo – laikrodis, ant piršto – žiedas.","k":"Kaip C paruošia ranką evakuacijai?"}]},{"id":"s40","src":"ETC","pav":"Galvos žaizda prie posto","tema":"Galva","lygis":"","st":[{"n":"1 klausimas","v":{"hr":88,"sys":130,"dia":80,"spo2":97,"rr":16,"temp":36.6},"p":"Prie posto sprogus minosvaidžio minai karys trenkėsi galva į betoninį bunkerio kraštą. Antrinėje apžiūroje A randa kraujuojančią galvos odos žaizdą, B siūlo ją užkimšti hemostatine marle. (GKS 14)","k":"Kaip tvarkoma galvos žaizda?"},{"n":"2 klausimas","v":{"hr":88,"sys":128,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Tikrindamas nosies landas A mato abipusį minkštą pertvaros patinimą, karys skundžiasi užgulta nosimi. (GKS 14)","k":"Ką nurodo A?"},{"n":"3 klausimas","v":{"hr":64,"sys":142,"dia":84,"spo2":95,"rr":16,"temp":36.6},"p":"Ruošiant evakuacijai karys tampa vis labiau mieguistas, kairės rankos ir kojos jėga silpnesnė nei dešinės. (GKS 11)","k":"Ką daro A?"}]},{"id":"s42","src":"ETC","pav":"Nurodymas „į orą“","tema":"Komanda","lygis":"","st":[{"n":"1 klausimas","v":{"hr":104,"sys":118,"dia":74,"spo2":97,"rr":22,"temp":36.6},"p":"Karys sužeistas minosvaidžio skeveldromis į šlaunį, kraujavimas sustabdytas, skausmas 8/10. Pirminės apžiūros metu A garsiai sako: „Kas nors paruoškite ketamino.“ Po minutės paaiškėja, kad niekas jo neruošia. (AVPU A)","k":"Kaip A turėjo duoti nurodymą?"},{"n":"2 klausimas","v":{"hr":104,"sys":118,"dia":74,"spo2":97,"rr":22,"temp":36.6},"p":"C narys Tomas pakartoja paskyrimą: 1 ml ketamino ampulės skiedžia iki 10 ml ir ketina suleisti 5 ml, kaip įpratęs. B narys pastebi, kad ant ampulės parašyta 100 mg/ml.","k":"Ką turi daryti B?"},{"n":"3 klausimas","v":{"hr":126,"sys":88,"dia":52,"spo2":94,"rr":22,"temp":36.6},"p":"Po pirminės apžiūros AKS netikėtai krenta. B vėl tikrina krūtinę, C keičia infuziją, A kalbasi su evakuacijos koordinatoriumi – komanda „įstrigo“, kiekvienas dirba atskirai.","k":"Ką daro A?"}]},{"id":"s43","src":"ETC","pav":"Perdavimas evakuacijai","tema":"Komanda","lygis":"","st":[{"n":"1 klausimas","v":{"hr":108,"sys":106,"dia":68,"spo2":96,"rr":16,"temp":36.6},"p":"Karys su šautine šlaunies žaizda stabilizuotas Role 1 punkte: turniketas nuo 09:40, 2 PVK, skirta TXA ir ketaminas. Sraigtasparnis nusileis po 5 min, pilotas ragina skubėti.","k":"Ką komanda daro prieš perkeldama pacientą ant neštuvų?"},{"n":"2 klausimas","v":{"hr":108,"sys":106,"dia":68,"spo2":96,"rr":16,"temp":36.6},"p":"Pacientas perkeliamas ant neštuvų. Dešinė blauzda įtvarinta dėl lūžio, ant kairės šlaunies – turniketas, pacientas dreba.","k":"Kaip teisingai supakuoti pervežimui?"},{"n":"3 klausimas","v":{"hr":108,"sys":106,"dia":68,"spo2":96,"rr":16,"temp":36.6},"p":"Prie sraigtasparnio laukia evakuacijos medikas, kuris pacientą veš chirurgams. Variklis veikia, triukšminga.","k":"Kada pacientas laikomas perduotu?"}]},{"id":"s44","src":"ETC","pav":"Kvėpavimas po opioidų","tema":"Vaistai","lygis":"","st":[{"n":"1 klausimas","v":{"hr":90,"sys":108,"dia":66,"spo2":86,"rr":7,"temp":36.6},"p":"Karys su atviru dilbio lūžiu po granatos sprogimo. Kovos medikas lauke suleido fentanilio į nosį, punkte titruotas morfinas IV. Po 15 min sužeistasis sunkiai pažadinamas, kvėpuoja retai. (AVPU P)","k":"Kas pirmiausia?"},{"n":"2 klausimas","v":{"hr":90,"sys":108,"dia":66,"spo2":93,"rr":8,"temp":36.6},"p":"A laiko kaukę, B ventiliuoja Ambu maišu, SpO₂ kyla. A skiria naloksono IV; C turi 0,4 mg / 1 ml ampulę ir 10 ml švirkštą.","k":"Kaip C paruošia ir leidžia naloksoną?"},{"n":"3 klausimas","v":{"hr":90,"sys":108,"dia":66,"spo2":95,"rr":14,"temp":36.6},"p":"Po 0,2 mg naloksono sužeistasis atsimerkia ir kvėpuoja pats. Skausmas 5/10. Evakuacija užtruks. (AVPU A)","k":"Kas toliau?"}]},{"id":"s45","src":"ETC","pav":"Pykinimas prieš skrydį","tema":"Vaistai","lygis":"","st":[{"n":"1 klausimas","v":{"hr":112,"sys":102,"dia":64,"spo2":95,"rr":16,"temp":36.6},"p":"Karys sužeistas drono numesta granata: skeveldros pilve, dešinėje krūtinės pusėje ir šlaunyje, pilvas įtemptas. Skirtas ketaminas, ruošiamasi sraigtasparnio evakuacijai. Sužeistąjį pykina, jis žiaukčioja. (AVPU A)","k":"Kurį antiemetiką skirti?"},{"n":"2 klausimas","v":{"hr":112,"sys":102,"dia":64,"spo2":95,"rr":16,"temp":36.6},"p":"C ruošia ondansetroną pagal skiedimo lentelę: 8 mg + 16 ml NaCl = 0,4 mg/ml, 20 ml švirkšte.","k":"Kiek ml reikia 4 mg dozei?"},{"n":"3 klausimas","v":{"hr":112,"sys":102,"dia":64,"spo2":94,"rr":16,"temp":36.6},"p":"Prieš skrydį A peržiūri pacientą: dešinėje – pleuros drenas, įvestas ŠPK, deguonies balionas pusiau tuščias.","k":"Į ką atsižvelgti dėl skrydžio aukštyje?"}]},{"id":"s46","src":"ETC","pav":"Nudegimai: plotas ir skysčiai","tema":"Nudegimai","lygis":"","st":[{"n":"1 klausimas","v":{"hr":124,"sys":92,"dia":58,"spo2":97,"rr":26,"temp":36.6},"p":"Į šarvuotį pataikius prieštankinei raketai, užsidegė vidus. Atvežtas vairuotojas: nudegęs liemuo ir dešinė ranka, iš kairės šlaunies skeveldros žaizdos pulsuojamai bėga kraujas. (AVPU V)","k":"Ką komanda sprendžia pirmiausia?"},{"n":"2 klausimas","v":{"hr":124,"sys":92,"dia":58,"spo2":97,"rr":26,"temp":36.6},"p":"Kraujavimas sustabdytas turniketu. Antrinėje apžiūroje: liemens priekis ir visa dešinė ranka – pūslės ir balti plotai, veidas tik paraudęs, be pūslių.","k":"Koks nudegimo plotas pagal devyneto taisyklę?"},{"n":"3 klausimas","v":{"hr":114,"sys":104,"dia":66,"spo2":97,"rr":26,"temp":36.6},"p":"Vairuotojas sveria 80 kg, nudegimai 27 % KPP, trauma įvyko prieš 1 val. A skiria Ringerio laktatą pagal Parkland formulę (2–4 ml × kg × % KPP per 24 val.), pradžiai imdamas 4 ml.","k":"Kiek skysčių reikia per pirmas 8 valandas?"}]},{"id":"s47","src":"ETC","pav":"Cheminis nudegimas","tema":"Nudegimai","lygis":"","st":[{"n":"1 klausimas","v":{"hr":98,"sys":120,"dia":78,"spo2":97,"rr":20,"temp":36.6},"p":"Artilerijos smūgis į technikos parką: sprogusi talpa apibėrė karį sausomis cheminėmis medžiagomis. Ant uniformos ir dilbių – milteliai, oda parausta, dilbiuose pūslės. (AVPU A)","k":"Ką daryti pirmiausia, užtikrinus savo saugumą?"},{"n":"2 klausimas","v":{"hr":98,"sys":120,"dia":78,"spo2":97,"rr":20,"temp":36.6},"p":"Nuplovus matyti, kad abu dilbiai nudegę ratu. Ant kairės rankos – laikrodis ir žiedas, pirštai pradeda tinti.","k":"Kaip sutvarkyti rankas?"},{"n":"3 klausimas","v":{"hr":96,"sys":128,"dia":80,"spo2":97,"rr":20,"temp":36.6},"p":"Nudegimai – apie 9 % KPP. Rašytojas klausia, ar skirti ceftriaksono ir pradėti skysčius pagal Parkland formulę.","k":"Koks teisingas sprendimas?"}]},{"id":"s48","src":"ETC","pav":"Užsitęsusi evakuacija","tema":"Nudegimai","lygis":"","st":[{"n":"1 klausimas","v":{"hr":116,"sys":110,"dia":68,"spo2":97,"rr":16,"temp":34.8},"p":"Dėl dronų grėsmės evakuacija atidėta 6 val. Kulkosvaidininkas su 35 % KPP nudegimais po BMP gaisro guli priedangoje ant betono grindų, tvarsčiai ir drabužiai permirkę, jis dreba.","k":"Kaip valdyti hipotermiją?"},{"n":"2 klausimas","v":{"hr":116,"sys":112,"dia":70,"spo2":97,"rr":20,"temp":35.2},"p":"Pacientas šildomas, bet skausmas 8/10, jis neramus. Veikia PVK, sveria 80 kg. (AVPU A)","k":"Kaip malšinti skausmą?"},{"n":"3 klausimas","v":{"hr":112,"sys":108,"dia":66,"spo2":97,"rr":20,"temp":35.2},"p":"Įvestas ŠPK, skysčiai lašinami pagal formulę. Per pastarąsias 2 val. surinkta 60 ml šlapimo.","k":"Kaip vertinti diurezę?"}]},{"id":"s49","src":"ETC","pav":"Skausmas keliems sužeistiesiems","tema":"Vaistai","lygis":"","st":[{"n":"1 klausimas","v":{"hr":128,"sys":86,"dia":50,"spo2":97,"rr":24,"temp":36.6},"p":"Po minosvaidžio apšaudymo vienu metu atvežti trys sužeistieji. Pirmasis – skeveldra šlaunyje, kraujavimas sustabdytas, blyškus, prakaituoja, skausmas 9/10, veikia PVK. (AVPU A)","k":"Kokia analgezija saugiausia?"},{"n":"2 klausimas","v":{"hr":96,"sys":132,"dia":84,"spo2":97,"rr":24,"temp":36.6},"p":"Antrasis – atviras blauzdos lūžis, kraujavimo nėra, hemodinamika stabili, skausmas 7/10. PVK dar neįvestas, nosis švari. (AVPU A)","k":"Kaip greitai nuskausminti?"},{"n":"3 klausimas","v":{"hr":88,"sys":124,"dia":78,"spo2":97,"rr":24,"temp":36.6},"p":"Trečiasis – paviršinės skeveldrų žaizdos dilbyje, sutvarstytos. Skausmas 3/10, sąmoningas, gali gerti. (AVPU A)","k":"Ką skirti?"}]},{"id":"s50","src":"ETC","pav":"Ketamino pompa pervežimui","tema":"Vaistai","lygis":"","st":[{"n":"1 klausimas","v":{"hr":102,"sys":118,"dia":72,"spo2":97,"rr":16,"temp":36.6},"p":"Karys su dubens ir šlaunies lūžiais po šarvuočio apvirtimo laukia ilgos evakuacijos. A skiria ketamino infuziją švirkštine pompa. C randa tik 100 mg/ml ampules. (AVPU A)","k":"Kaip paruošti 50 ml švirkštą, kad būtų 10 mg/ml?"},{"n":"2 klausimas","v":{"hr":102,"sys":118,"dia":72,"spo2":97,"rr":16,"temp":36.6},"p":"Švirkštas paruoštas ir paženklintas: ketaminas 10 mg/ml. Karys sveria 80 kg, paskirta pradėti nuo 0,5 mg/kg/val.","k":"Kokį greitį nustatyti pompoje?"},{"n":"3 klausimas","v":{"hr":102,"sys":118,"dia":72,"spo2":96,"rr":16,"temp":36.6},"p":"Atvyksta evakuacinė mašina. Lašinamas šildytas tirpalas, veikia ketamino pompa, ant rankų – dvi linijos. (AVPU A)","k":"Ką C turi užtikrinti prieš pervežimą?"}]},{"id":"m4","src":"March","pav":"Be sąmonės po skeveldros sužeidimo","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":10,"temp":36.6},"p":"Už kelių metrų sprogo minosvaidžio mina: skeveldra pataikė į šlaunį, masyvaus kraujavimo nėra. Sprogimo banga parbloškė karį – jis be sąmonės (uždara galvos trauma), guli ant nugaros ir knarkia. Kaklo trauma neįtariama. (AVPU U)","k":"Ką darote?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":14,"temp":36.6},"p":"Takai atverti, knarkimas dingo, kvėpuoja pakankamai. Reikia eiti prie kitų MARCH veiksmų.","k":"Kokioje padėtyje paliekate?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":84,"rr":6,"temp":36.6},"p":"Po 10 min kvėpavimas suretėjo ir tapo paviršinis, SpO₂ nekyla. Kaukolės pamato lūžio požymių nėra. (AVPU U)","k":"Ką darote?"}]},{"id":"m5","src":"March","pav":"Šautinė krūtinės žaizda","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":24,"temp":36.6},"p":"Šautinė žaizda dešinėje krūtinės pusėje; įkvepiant girdėti siurbiantis garsas, burbuliuoja kraujas. (AVPU A)","k":"Ką darote?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":86,"rr":36,"temp":36.6},"p":"Po 10 min kvėpavimas vis dažnėja, distresas didėja, dešinėje kvėpavimo garsai labai susilpnėję.","k":"Ką darote pirmiausia?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":82,"rr":40,"temp":36.6},"p":"Atpūtus lipduką būklė nepagerėjo.","k":"Kaip atliekate adatinę dekompresiją (NDC)?"}]},{"id":"m6","src":"March","pav":"Pėdos amputacija ir šokas (CMC)","tema":"TFC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":128,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"Mina nutraukė pėdą prieš 30 min; turniketas veiksmingas. Sužeistasis mieguistas, atsimerkia tik užkalbintas. Galvos traumos požymių nėra. (AVPU V, Radialinis pulsas silpnas)","k":"Ar sužeistasis šoke?"},{"n":"2 klausimas","v":{"hr":128,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) IO prieiga įvesta. Nuo sužeidimo praėjo 40 min. (AVPU V, Radialinis pulsas silpnas)","k":"(CMC) Kaip skiriate TXA?"},{"n":"3 klausimas","v":{"hr":128,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Perpilamas šaltai laikytas mažo titro O pilnas kraujas; pirmasis vienetas baigtas. (Radialinis pulsas silpnas)","k":"(CMC) Ką skiriate po pirmojo vieneto?"}]},{"id":"m7","src":"March","pav":"Galvos trauma lyjant","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Sprogimas prieš 15 min. Sužeistasis nevykdo paprastų komandų, kraujavimo nėra, radialinis pulsas stiprus. Prie jo – ginklas ir granatos. (AVPU V, Radialinis pulsas stiprus)","k":"Ką darote pirmiausia?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":88,"rr":8,"temp":36.6},"p":"Kvėpuoja retai ir paviršiškai, SpO₂ nepakyla. Įtariate vidutinę ar sunkią galvos smegenų traumą.","k":"Koks tikslas ir veiksmai?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":94,"rr":8,"temp":36.6},"p":"Ventiliacija veikia, šoko nėra. Lyja, sužeistasis guli ant šlapios žemės. (Radialinis pulsas stiprus)","k":"Kas teisinga?"}]},{"id":"m9","src":"March","pav":"Apvirtęs šarvuotis (CMC)","tema":"TFC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":124,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Apvirto šarvuotis. Sunki buka trauma, stiprus dubens skausmas, matomo kraujavimo nėra. (AVPU A, Radialinis pulsas silpnas)","k":"(CMC) Kur dedate dubens diržą?"},{"n":"2 klausimas","v":{"hr":124,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Diržas uždėtas. Skausmas 9/10, užduoties tęsti negali, sąmoningas. Planuojate ketaminą. (AVPU A, Skausmas 9/10)","k":"(CMC) Ką būtina padaryti prieš ketaminą?"},{"n":"3 klausimas","v":{"hr":124,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Antrasis CMC dar įvedinėja IO ir ruošia TXA, skausmas nemažėja. Kad nelauktumėte prieigos, ketaminą skiriate į raumenis.","k":"(CMC) Dozė ir kartojimas?"}]},{"id":"m10","src":"March","pav":"MEDEVAC ir perdavimas","tema":"TACEVAC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Sužeistasis su turniketu ant šlaunies paruoštas evakuacijai. Vadas liepia kviesti MEDEVAC, bet dalies duomenų dar trūksta.","k":"Kurių 9-Line eilučių reikia priemonei išsiųsti?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Sužeistasis perkeltas ant neštuvų ir į transporto priemonę. Turniketas uždėtas prieš 50 min. (AVPU A, Radialinis pulsas stiprus)","k":"Ką darote po perkėlimo?"},{"n":"3 klausimas","v":{"hr":96,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Atvykote į stabilizavimo punktą. Aplink triukšminga, priimantis medikas skuba. (AVPU A)","k":"Kaip perduodate sužeistąjį?"}]},{"id":"m21","src":"March","pav":"Veido žaizda: leiskite sėdėti","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":20,"temp":36.6},"p":"Minosvaidžio sviedinio skeveldra pataikė kariui į skruostą ir nosį, kraujas teka į burną. Jis sąmoningas, atsako, nori sėdėti, o kolega bando jį paguldyti ant nugaros. (AVPU A)","k":"Kokią padėtį pasirenkate?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":20,"temp":36.6},"p":"Kolega siūlo stabilizuoti kaklą ir visą laiką rankomis laikyti galvą. Kitų sužalojimų, išskyrus skeveldros žaizdas, nėra; karys nekrito ir nebuvo nusviestas. (AVPU A)","k":"Ar reikia stabilizuoti kaklą?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":10,"temp":36.6},"p":"Laukiant evakuacijos, karys apsnūsta, atsimerkia tik nuo skausmo, gargaliuoja, burnoje kraujas. Jis susmunka ant šono. (AVPU P)","k":"Ką darote?"}]},{"id":"m22","src":"March","pav":"Sudarkytas žandikaulis (CMC)","tema":"TFC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":88,"rr":28,"temp":36.6},"p":"(CMC) Drono numesta granata sprogo prie apkaso. Kario apatinis žandikaulis sudarkytas, jis guli, gargaliuoja, burnoje kraujas ir dantų skeveldros. Šalia yra CLS. (AVPU V)","k":"(CMC) Ką darote pirmiausia?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":82,"rr":32,"temp":36.6},"p":"(CMC) Nepaisant atsiurbimo ir padėties, kraujas vis užlieja ryklę, oras beveik nepraeina, SpO₂ krenta.","k":"(CMC) Ką darote?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":85,"rr":32,"temp":36.6},"p":"(CMC) Kaniulė įvesta ant bužo, manžetė pripūsta 10 ml oro. Dešinėje kvėpavimas girdimas, kairėje – ne, krūtinė kyla nevienodai.","k":"(CMC) Ką darote?"}]},{"id":"m23","src":"March","pav":"Lipdukas ir nugaros žaizda","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":26,"temp":36.6},"p":"Patrulio metu granatos skeveldra pataikė kariui į kairę krūtinės pusę. Priekinę burbuliuojančią žaizdą jau užklijavote ventiliuojamu lipduku. (AVPU A)","k":"Ką darote toliau R dalyje?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":28,"temp":36.6},"p":"Nugaroje, virš apatinių šonkaulių, – dar viena burbuliuojanti žaizda. Krūtinės lipdukų nebeliko, turite plastikinį maišelį ir lipnią juostą.","k":"Kaip sandarinate?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":87,"rr":34,"temp":36.6},"p":"Perkėlus ant neštuvų, kvėpavimas dažnėja, distresas didėja, kairėje kvėpavimo garsai labai susilpnėję.","k":"Ką darote pirmiausia?"}]},{"id":"m24","src":"March","pav":"NDC po sprogimo bangos","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":84,"rr":36,"temp":36.6},"p":"Prie kolonos sprogo SSU; karį sprogimo banga nusviedė nuo šarvuočio. Krūtinėje žaizdų nėra, bet jis dūsta, dešinėje kvėpavimas negirdimas. (AVPU A)","k":"Ką darote?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":89,"rr":28,"temp":36.6},"p":"NDC atlikta 5-ajame tarpšonkaulyje priekinėje pažasties linijoje. Dėl variklių triukšmo šnypštimo negirdėjote, bet karys kvėpuoja lengviau, SpO₂ lėtai kyla.","k":"Kaip vertinate NDC?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":86,"rr":34,"temp":36.6},"p":"Po 20 min, laukiant evakuacijos, distresas vėl didėja, dešinėje kvėpavimo garsai vėl susilpnėję.","k":"Ką darote?"}]},{"id":"m25","src":"March","pav":"NDC nepadėjo","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":84,"rr":38,"temp":36.6},"p":"Artilerijos skeveldra – kairėje krūtinės pusėje. Lipdukas užklijuotas ir „atpūstas“, bet distresas didėja. Duriate NDC 5-ajame tarpšonkaulyje priekinėje pažasties linijoje, adata įvesta iki jungties.","k":"Ką darote su adata?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":82,"rr":38,"temp":36.6},"p":"Po kelių minučių distresas nesumažėjo, kairėje kvėpavimas vis dar negirdimas.","k":"Ką darote toliau?"},{"n":"3 klausimas","v":{"hr":132,"sys":120,"dia":78,"spo2":82,"rr":38,"temp":36.6},"p":"Nepadėjo ir antra NDC. Karys sumišęs, odą išpylė šaltas prakaitas, galvos traumos požymių nėra. (AVPU V, Radialinis pulsas silpnas)","k":"Ką darote?"}]},{"id":"m26","src":"March","pav":"Sprogimo banga ir dubuo","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Pėsčiųjų patrulio narį nusviedė SSU sprogimas. Kairė blauzda beveik nutraukta, turniketas uždėtas, kraujavimas sustojo. Jūs – CLS, apmokytas dėti dubens diržą. (AVPU A, Radialinis pulsas čiuopiamas, Skausmas 8/10)","k":"Ar reikia dubens diržo?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Komercinio dubens diržo nėra. Turite skarą, kišenėse – žiebtuvėlis ir šovinių dėtuvė.","k":"Kaip elgiatės?"},{"n":"3 klausimas","v":{"hr":128,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Laukiant evakuacijos, po 15 min karys tampa mieguistas, radialinis pulsas susilpnėja. Turniketo vieta nekraujuoja. (AVPU V, Radialinis pulsas silpnas)","k":"Ką darote?"}]},{"id":"m27","src":"March","pav":"Šokas be matomo kraujavimo (CMC)","tema":"TFC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":26,"temp":36.6},"p":"Minosvaidžio skeveldra pataikė į pilvą žemiau šonkaulių; įėjimo anga maža, išorinis kraujavimas menkas. Po 20 min karys atsimerkia ir sudejuoja tik spaudžiant nago guolį. Galvos traumos požymių nėra.","k":"Kaip vertinate sąmonę?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":26,"temp":36.6},"p":"Dešinysis dilbis sužeistas, ant jo – turniketas. Kairioji ranka sveika. (AVPU P)","k":"Kaip čiuopiate radialinį pulsą?"},{"n":"3 klausimas","v":{"hr":130,"sys":120,"dia":78,"spo2":97,"rr":26,"temp":36.6},"p":"(CMC) Radialinis pulsas silpnas, dažnas. (AVPU P, Radialinis pulsas silpnas)","k":"(CMC) Ką darote?"}]},{"id":"m28","src":"March","pav":"TXA laiko langas (CMC)","tema":"TFC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":126,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) 13:10 drono numesta granata sužeidė du karius apkase; dėl dronų grėsmės juos pasiekiate tik 15:30. Pirmajam – turniketas ant šlaunies, jis šoke. Dešinysis žastas subjaurotas skeveldrų, du IV bandymai nepavyko. (AVPU V, Radialinis pulsas silpnas)","k":"(CMC) Kur įvedate prieigą?"},{"n":"2 klausimas","v":{"hr":126,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) 15:45 IO veikia. Nuo sužeidimo praėjo 2 val. 35 min. (Radialinis pulsas silpnas)","k":"(CMC) Ar skiriate TXA?"},{"n":"3 klausimas","v":{"hr":126,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Antrasis karys iš to paties apkaso: išorinio kraujavimo nėra, radialinis pulsas stiprus, bet po sprogimo jis sumišęs. (AVPU V, Radialinis pulsas stiprus)","k":"(CMC) Ar jam reikia TXA?"}]},{"id":"m29","src":"March","pav":"Kraujo perpylimas lauke (CMC)","tema":"TFC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":134,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Kuopos medicinos punkte – karys po šautinės šlaunies žaizdos, šoke; turniketas veiksmingas, IO veikia, TXA suleista. Turite tik šaltai laikyto mažo titro O Rh teigiamo pilno kraujo, EldonCard dar nepadaryta. (AVPU V, Radialinis pulsas silpnas)","k":"(CMC) Ką darote?"},{"n":"2 klausimas","v":{"hr":134,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Ruošiate perpylimo sistemą. Kolega siūlo sutaupyti laiko.","k":"(CMC) Kaip perpilate?"},{"n":"3 klausimas","v":{"hr":108,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Pirmasis vienetas baigtas, 30 ml 10 % kalcio gliukonato suleista. Radialinis pulsas čiuopiamas, karys atsimerkęs, atsako aiškiai. (AVPU A, Radialinis pulsas čiuopiamas)","k":"(CMC) Ar pilate antrą vienetą?"}]},{"id":"m30","src":"March","pav":"Trauminis sustojimas po šūvio","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":66,"dia":40,"spo2":97,"rr":0,"temp":36.6},"p":"Snaiperio kulka pataikė kariui į krūtinę. Jį ištraukus už priedangos, miego arterijos pulso nėra, nekvėpuoja, kitų gyvybės požymių nėra. Netoliese – dar vienas sužeistasis. (AVPU U, Radialinis pulsas nečiuopiamas)","k":"Ką darote?"},{"n":"2 klausimas","v":{"hr":90,"sys":66,"dia":40,"spo2":97,"rr":0,"temp":36.6},"p":"Ruošiatės NDC. Kulkos anga – dešinėje, kairė krūtinės pusė nesužeista.","k":"Kaip atliekate NDC?"},{"n":"3 klausimas","v":{"hr":90,"sys":66,"dia":40,"spo2":97,"rr":0,"temp":36.6},"p":"Abipusė NDC atlikta. Sąmonė ir radialinis pulsas negrįžta. (AVPU U, Radialinis pulsas nečiuopiamas)","k":"Ką darote?"}]},{"id":"m31","src":"March","pav":"Kritimas į upę forsuojant","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":104,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Forsuojant upę naktį skeveldra sužeidė kario dilbį – jis įkrito į šaltą vandenį. Ištrauktas į krantą už priedangos, turniketas veiksmingas, drabužiai permirkę, karys stipriai dreba. (AVPU A, Radialinis pulsas stiprus)","k":"Kada pradedate hipotermijos prevenciją?"},{"n":"2 klausimas","v":{"hr":104,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Karys guli ant akmenuoto kranto, pučia vėjas. Turite šildantį apvalkalą, aktyvaus šildymo antklodę ir sausą aprangos komplektą. (AVPU A, Radialinis pulsas stiprus)","k":"Kas teisinga?"},{"n":"3 klausimas","v":{"hr":104,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Karys guli išskleisto šildančio apvalkalo viduryje, bus vežamas atviru visureigiu. Atidarote aktyvaus šildymo antklodę. (AVPU A)","k":"Kaip ją uždedate?"}]},{"id":"m33","src":"March","pav":"Pilvo evisceracija","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":112,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Prie posto sprogo minosvaidžio mina. Karys turi skeveldros žaizdą pilve – pro ją iškritusios žarnų kilpos. Masyvaus kraujavimo nėra. (AVPU A, Radialinis pulsas stiprus)","k":"Ką darote su iškritusiais organais?"},{"n":"2 klausimas","v":{"hr":112,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Žaizda uždengta. Karys skundžiasi stipriu skausmu, prašo vandens ir tablečių nuo skausmo. (AVPU A, Skausmas 8/10)","k":"Ką darote?"},{"n":"3 klausimas","v":{"hr":112,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Sužeistąjį perkeliate ant neštuvų ir nešate į evakuacijos punktą; lauke šlapdriba. (AVPU A, Radialinis pulsas stiprus)","k":"Ką darote po perkėlimo?"}]},{"id":"m35","src":"March","pav":"Šarvuočio gaisras: nudegimai","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":118,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"Prieštankinė raketa pataikė į šarvuotį, jis užsidegė. Vairuotoją ištraukėte su rūkstančia uniforma, degimą užgesinote; kairės blauzdos skeveldros žaizda smarkiai kraujuoja. (AVPU A, Radialinis pulsas silpnas)","k":"Ką darote pirmiausia?"},{"n":"2 klausimas","v":{"hr":118,"sys":86,"dia":54,"spo2":97,"rr":16,"temp":36.6},"p":"Kraujavimas sustabdytas. Nudegusi visa liemens priekinė dalis, visa dešinė ranka ir dar trys delno dydžio plotai ant kaklo. (AVPU A, Radialinis pulsas silpnas)","k":"Koks plotas ir ką tai lemia?"},{"n":"3 klausimas","v":{"hr":118,"sys":86,"dia":54,"spo2":91,"rr":24,"temp":36.6},"p":"Šarvuotyje buvo daug dūmų. Po 10 min karys užkimsta ir kosti, antakiai apsvilę, veidas paraudęs, nosyje ir burnoje – suodžiai. (AVPU A)","k":"Kas teisinga?"}]},{"id":"m37","src":"March","pav":"Be sąmonės: nieko per burną","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":14,"temp":36.6},"p":"Artilerijos sviedinys sprogo apie 20 m nuo apkaso. Karys reaguoja tik į skausmą, dilbio skeveldros žaizda sutvarstyta. Draugas nori įdėti jam į burną CWMP ir cefadroksilį. (AVPU P, Radialinis pulsas stiprus)","k":"Ką atsakote draugui?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":14,"temp":36.6},"p":"Sužeistasis guli ant nugaros ir pradeda vemti. (AVPU P)","k":"Ką darote?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":94,"rr":14,"temp":36.6},"p":"Pakartotinai vertinant po 10 min: kairysis vyzdys išsiplėtęs ir nereaguoja, dešinysis – normalus. (AVPU P, Radialinis pulsas stiprus)","k":"Ką darote?"}]},{"id":"m38","src":"March","pav":"Ketaminas ir jo poveikis (CMC)","tema":"TFC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Granatos skeveldros sužeidė abi kario kojas; kraujavimas sustabdytas, CWMP išgertas, užduoties tęsti negali. IV / IO prieigos nėra; turite 100 mg/ml ketamino ir purkštuvą. (AVPU A, Radialinis pulsas stiprus, Skausmas 8/10)","k":"(CMC) Kokią dozę skiriate į nosį?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Po 15 min skausmas 4/10, bet karys sujaudintas, dezorientuotas ir jį pykina. (AVPU A, Skausmas 4/10)","k":"(CMC) Ką darote?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":89,"rr":7,"temp":36.6},"p":"(CMC) Pervežant pastebite, kad kvėpavimas suretėjo ir tapo paviršinis. (AVPU V)","k":"(CMC) Kokie veiksmai?"}]},{"id":"m39","src":"March","pav":"Žandikaulio žaizda (CMC)","tema":"TFC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":95,"rr":16,"temp":36.6},"p":"(CMC) Snaiperio kulka sužalojo kario apatinį žandikaulį. Jis sėdi pasilenkęs į priekį, kvėpavimo takai laisvi, kraujavimas sustabdytas; nuryti negali. (AVPU A, Radialinis pulsas stiprus)","k":"(CMC) Kokį antibiotiką skiriate?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":95,"rr":16,"temp":36.6},"p":"(CMC) IV / IO prieigos nėra – ceftriaksoną 2 g leisite į raumenis.","k":"(CMC) Kaip suleidžiate?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":95,"rr":16,"temp":36.6},"p":"(CMC) Skausmas 8/10, užduoties tęsti negali. CWMP dar negavo. (AVPU A, Skausmas 8/10)","k":"(CMC) Kaip nuskausminate?"}]},{"id":"m43","src":"March","pav":"Turniketas šarvuotyje","tema":"TACEVAC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Sužeistąjį su turniketu ant šlaunies (uždėtas apšaudymo metu 1410L) vežate šarvuočiu duobėtu keliu. Po stipraus krestelėjimo tvarstis ant žaizdos žemiau turniketo greitai permirksta, pėdoje čiuopiamas pulsas. (AVPU A, Radialinis pulsas stiprus)","k":"Ką darote?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Antrasis turniketas uždėtas 1455L; kraujavimas sustojo, distalinio pulso nebėra. (AVPU A, Radialinis pulsas stiprus)","k":"Kaip užrašote laikus?"},{"n":"3 klausimas","v":{"hr":128,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Po 10 min sužeistasis išblyškęs, atsako tik užkalbintas, radialinis pulsas silpnas. Iki stabilizavimo punkto – 20 min. (AVPU V, Radialinis pulsas silpnas)","k":"Kas svarbiausia dabar?"}]},{"id":"m44","src":"March","pav":"Dusulys sraigtasparnyje","tema":"TACEVAC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":118,"sys":86,"dia":54,"spo2":85,"rr":36,"temp":36.6},"p":"Lydite sužeistąjį su šautine krūtinės žaizda sraigtasparnyje; ventiliuojamas krūtinės lipdukas uždėtas. Po pakilimo dusulys sparčiai didėja, triukšme kvėpavimo garsų neišgirsite. (AVPU A, Radialinis pulsas silpnas)","k":"Ką darote pirmiausia?"},{"n":"2 klausimas","v":{"hr":118,"sys":86,"dia":54,"spo2":82,"rr":40,"temp":36.6},"p":"Lipduką atpūtus būklė nepagerėjo; SpO₂ toliau krenta, sužeistasis neramus. (Radialinis pulsas silpnas)","k":"Kur atliekate NDC?"},{"n":"3 klausimas","v":{"hr":118,"sys":86,"dia":54,"spo2":92,"rr":24,"temp":36.6},"p":"Po NDC oro šnypštimo dėl triukšmo neišgirdote, bet kvėpuoti akivaizdžiai lengviau. (Radialinis pulsas stiprus)","k":"Kaip vertinate?"}]},{"id":"m46","src":"March","pav":"Ilgas laukimas poste","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Dėl dronų grėsmės evakuacija atidėta apie 3 val. Kariui skeveldra sužeidė dilbį; turniketas uždėtas apšaudymo metu prieš 40 min. Šoko nėra, žaizdą galite stebėti, amputacijos nėra. (AVPU A, Radialinis pulsas stiprus)","k":"Ką darote su turniketu?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Kraujavimas nesikartoja. Karys budrus, gali nuryti, alergijų neturi. (AVPU A, Skausmas 6/10)","k":"Ką duodate?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":26,"temp":36.6},"p":"Po 1,5 val. karys mieguistas, atsimerkia tik užkalbintas. Draugas sako: „Tai nuo tablečių – tegul miega.“ (AVPU V, Radialinis pulsas silpnas)","k":"Ką darote?"}]},{"id":"m47","src":"March","pav":"Neštuvai žiemą","tema":"TFC","lygis":"CLS","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Žiemos operacija, −10 °C, sninga. Minosvaidžio skeveldra sužeidė karį į blauzdą; turniketas veiksmingas. Iki transporto – 800 m miško keliu į kalvą. (AVPU A, Radialinis pulsas stiprus)","k":"Kaip paruošiate jį nešti?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Sužeistasis pritvirtintas neštuvų diržais. Keturi nešėjai pradeda kilti į kalvą.","k":"Kaip nešate?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":20,"temp":36.6},"p":"Sustojus pailsėti pastebite, kad apvalkalas prasiskyrė, viduje – šlapias sniegas; sužeistasis dreba. (AVPU A)","k":"Ką darote sustoję?"}]},{"id":"m49","src":"March","pav":"Ketaminas pervežant (CMC)","tema":"TACEVAC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"Sunkvežimis užvažiavo ant minos. Vairuotojo šlaunikaulio lūžis įtvertas, IV prieiga įvesta. Vežate jį sanitariniu šarvuočiu; skausmas nepakenčiamas, užduoties tęsti negali. (AVPU A, Radialinis pulsas stiprus, Skausmas 8/10)","k":"(CMC) Ką padarote prieš skirdami ketaminą?"},{"n":"2 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":97,"rr":16,"temp":36.6},"p":"(CMC) Alergijų nėra, ginklas paimtas, AVPU ir skausmas įrašyti. IV prieiga veikia. (AVPU A, Skausmas 8/10)","k":"(CMC) Kaip skiriate ketaminą?"},{"n":"3 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":96,"rr":18,"temp":36.6},"p":"(CMC) Po 10 min sužeistasis neramus, blaškosi ant neštuvų ir pradeda vemti. (Skausmas 3/10)","k":"(CMC) Ką darote?"}]},{"id":"m50","src":"March","pav":"Galvos trauma skrydyje (CMC)","tema":"TACEVAC","lygis":"CMC","st":[{"n":"1 klausimas","v":{"hr":90,"sys":120,"dia":78,"spo2":89,"rr":16,"temp":36.6},"p":"Artilerijos sviedinys sprogo 20 m nuo kario; skeveldra sužeidė pilvą, išorinio kraujavimo nėra. Praėjus 30 min jis vis dar nevykdo paprastų komandų, vyzdžiai simetriški. Skrendate sraigtasparniu; kvėpuoja savarankiškai. (AVPU V, Radialinis pulsas stiprus)","k":"(CMC) Ar skiriate deguonį?"},{"n":"2 klausimas","v":{"hr":124,"sys":120,"dia":78,"spo2":93,"rr":16,"temp":36.6},"p":"(CMC) Po 10 min radialinis pulsas susilpnėjo, sAKS 88 mm Hg. Turite kraujo. (AVPU V, Radialinis pulsas silpnas)","k":"(CMC) Koks prioritetas?"},{"n":"3 klausimas","v":{"hr":124,"sys":120,"dia":78,"spo2":93,"rr":16,"temp":36.6},"p":"(CMC) Prieš nusileidžiant kairysis vyzdys išsiplėtęs ir nereaguoja, atsiranda patologinė laikysena. (AVPU P, Radialinis pulsas silpnas)","k":"(CMC) Ką skiriate?"}]}];
